```python
class Sal:
    def __init__(self, navn, kapasitet):
        self._navn = navn
        self._kapasitet = kapasitet
        self._paameldte = 0

    def ledige(self):
        return self._kapasitet - self._paameldte

    def meld_paa(self, antall):
        if antall > self.ledige():
            print("Ikke plass")
        else:
            self._paameldte = self._paameldte + antall

s = Sal("Speilsal", 10)
s.meld_paa(7)
s.meld_paa(5)
print(s.ledige())
